	/** 
	 * jumpstart the process by instantiating2 Site
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		siteId = SiteService.getSiteInstance()
		.createSite( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		SiteService.getSiteInstance()
				.createSite( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.siteSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Site : " + successValue.getSiteId());
							  if (successValue.getSiteId().equals(siteId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfSiteList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Site test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on site consumed")
					);
			subscriber.siteSubscribe( siteId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Site : " + successValue.getSiteId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfSiteList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on site for siteId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Site. 
	 */
	protected Site read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Site" );

		Site entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Site with primary key" );
		msg.append( siteId );
		
		SiteFetchOneSummary fetchOneSummary = new SiteFetchOneSummary( siteId );

		try {
			entity = SiteService.getSiteInstance().getSite( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Site " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Site.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Site." );

		StringBuilder msg = new StringBuilder( "Failed to update a Site : " );        
		Site entity = read();
		UpdateSiteCommand command = generateUpdateCommand();
		command.setSiteId(entity.getSiteId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Site." );

			// for use later on...
			siteId = entity.getSiteId();

			SiteService proxy = SiteService.getSiteInstance();  

			proxy.updateSite( command ).get();

			LOGGER.info( "-- Successfully saved Site - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + siteId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Site.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Site." );

		Site entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Site with id " + siteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Site with id " + siteId );

			throw e;
		}

		try{
			SiteService.getSiteInstance().delete( new DeleteSiteCommand( entity.getSiteId() ) ).get();
			LOGGER.info( "-- Successfully deleted Site with id " + siteId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Site with id " + siteId );

			throw e;
		}
	}

	/**
	 * get all Sites.
	 */
	protected List<Site> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Sites:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Site : " );        
		List<Site> collection  = new ArrayList<>();

		try {
			// call the static get method on the SiteService
			collection = SiteService.getSiteInstance().getAllSite();
			assertNotNull( collection, "An Empty collection of Site was incorrectly returned.");
			
			// Now print out the values
			Site entity = null;            
			Iterator<Site> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getSiteId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

